    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"foo": "foo_value"}

if __name__ == "__main__":
    try:
        test_reawaitable_dependency()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
