{"content": "import asyncio
import functools
from fastapi import FastAPI, Depends
from fastapi.testclient import TestClient
from typing import Any

# Custom decorator to simulate the issue
def reawaitable(func):
    @functools.wraps(func)
    async def wrapper(*args, **kwargs):
        return await func(*args, **kwargs)
    return wrapper

@functools.cache
def get_foo():
    return "foo_value"

# Wrap it with reawaitable to make it a coroutine
# But functools.cache makes it a cached function.
# The issue is that FastAPI should be able to handle wrapped coroutines.

async def dependency():
    return await get_foo_async()

@reawaitable
async def get_foo_async():
    return "foo_value"

app = FastAPI()

@app.get("/")
async def read_root(foo: str = Depends(get_foo_async)):
    return {"foo": foo}

def test_reawaitable_dependency():
    client = TestClient(app)
    response = client.get("/")
    assert response.status_code == 200
    assert response.json() == {"foo": "foo_value"}

if __name__ == "__main__":
    try:
        test_reawaitable_dependency()
        print("Test passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)
